using Microsoft.AspNetCore.HttpOverrides;
using System.Net.Http;

var builder = WebApplication.CreateBuilder(args);

// Breaking change fix #4: ValidateOnBuild/ValidateScopes enabled by default in dev.
// A scoped service (IUserService) cannot be resolved from the root provider in a
// singleton factory. Fix: register ICacheService as scoped, or use IServiceScopeFactory.
builder.Services.AddScoped<IUserService, UserService>();
builder.Services.AddScoped<ICacheService, CacheService>();

// Breaking change fix #1: HttpClientFactory now uses SocketsHttpHandler by default.
// Casting to HttpClientHandler throws InvalidCastException. Use ConfigurePrimaryHttpMessageHandler.
builder.Services.AddHttpClient("api")
    .ConfigurePrimaryHttpMessageHandler(() => new SocketsHttpHandler { UseCookies = false });

// Breaking change fix #2: HttpClientFactory Trace-level logs now redact all header values.
// Explicitly allow non-sensitive headers needed for debugging.
builder.Services.AddHttpClient("api")
    .RedactLoggedHeaders(header =>
        header != "X-Request-Id" &&
        header != "X-Forwarded-For" &&
        header != "X-Forwarded-Proto");

// Breaking change fix #3: ForwardedHeaders middleware now ignores unknown proxies.
// You MUST add your reverse proxy to KnownProxies or KnownNetworks.
builder.Services.Configure<ForwardedHeadersOptions>(options =>
{
    options.ForwardedHeaders = ForwardedHeaders.XForwardedFor | ForwardedHeaders.XForwardedProto;
    // Add your actual reverse proxy address(es) here:
    options.KnownProxies.Add(System.Net.IPAddress.Parse("10.0.0.1"));
});

var app = builder.Build();
app.UseForwardedHeaders();
app.Run();

// Stub services for compilation
public interface IUserService { }
public class UserService : IUserService { }
public interface ICacheService { }
public class CacheService : ICacheService
{
    public CacheService(IUserService userService) { }
}

